"""Module for parsing the auto-generated part of YouTube descriptions.

YouTube writes the description of songs that labels deliver to it, from
the data they send, in a fixed layout:

    Provided to YouTube by Label

    Title · Artist · Other Artist

    Album

    ℗ 2020 Label

    Released on: 2020-01-01

    Composer: Name
    Associated  Performer, Drums: Name

    Auto-generated by YouTube.

The copyright and release date lines can be missing. Uploaders
sometimes paste such a description into their own, with other text
before or after it, so it's looked for anywhere in a description.
"""
import re
from typing import Final

from retag_opus import utils, youtube_credits

Tags = dict[str, list[str]]

FIRST_LINE_PATTERN: Final = r"\s*Provided to YouTube by (.+?)\s*$"
LAST_LINE_PATTERN: Final = r"\s*Auto-generated by YouTube\.?\s*$"
TITLE_AND_ARTIST_SEPARATOR: Final = " · "
COPYRIGHT_PATTERN: Final = r"\s*℗ (.+?)\s*$"
COPYRIGHT_YEAR_PATTERN: Final = r"\s*℗ (\d\d\d\d)\s"
RELEASE_DATE_PATTERN: Final = r"\s*Released on:\s*(\d\d\d\d-\d\d-\d\d)"


def find(lines: list[str]) -> tuple[int, int] | None:
    """Find the auto-generated part of a description.

    It starts with "Provided to YouTube by", followed by the line with
    the title and artists, and ends with "Auto-generated by YouTube.".
    Copies that uploaders changed, e.g. by joining all lines into one,
    aren't found, since their layout can't be relied on.

    Example: in ["Our new video!", "Provided to YouTube by Label",
    "Song · Singer", "Album", "Auto-generated by YouTube.", "Follow
    us"], it's from index 1 to index 4.

    :param lines: The lines of a description, without empty lines.

    :return: The index of the first and the last line of the
        auto-generated part, or None if there isn't one.
    """
    for first_index, first_line in enumerate(lines):
        if not re.match(FIRST_LINE_PATTERN, first_line):
            continue
        title_line_index = first_index + 1
        has_title_line = title_line_index < len(lines) and TITLE_AND_ARTIST_SEPARATOR in lines[title_line_index]
        if not has_title_line:
            continue
        for last_index in range(title_line_index + 1, len(lines)):
            if re.match(LAST_LINE_PATTERN, lines[last_index]):
                return first_index, last_index
    return None


def parse(lines: list[str]) -> Tags:
    """Parse the auto-generated part of a description by its layout.

    Credits are read by youtube_credits. Without a release date, the
    year of the copyright is used as the date.

    :param lines: The lines of the auto-generated part, from "Provided
        to YouTube by" to "Auto-generated by YouTube.", without empty
        lines.

    :return: The tags in the auto-generated part.
    """
    tags: Tags = {}
    first_line_match = re.match(FIRST_LINE_PATTERN, lines[0])
    if first_line_match:
        tags["organization"] = [first_line_match.group(1)]

    title_and_artists = lines[1].strip().split(TITLE_AND_ARTIST_SEPARATOR)
    tags["title"] = [title_and_artists[0]]
    artists = title_and_artists[1:]
    # Some labels list all artists after one separator, e.g. "Song · A, B"
    if len(artists) == 1 and ", " in artists[0]:
        artists = utils.split_tag(artists[0])
    if artists:
        tags["artist"] = utils.remove_duplicates(artists)

    # The last line is "Auto-generated by YouTube."
    last_index = len(lines) - 1
    album_index = 2
    if album_index < last_index:
        tags["album"] = [lines[album_index].strip()]

    copyright_year = None
    first_credit_index = album_index + 1
    for line in lines[first_credit_index:last_index]:
        copyright_match = re.match(COPYRIGHT_PATTERN, line)
        release_date_match = re.match(RELEASE_DATE_PATTERN, line)
        if copyright_match:
            tags["copyright"] = [copyright_match.group(1)]
            copyright_year_match = re.match(COPYRIGHT_YEAR_PATTERN, line)
            if copyright_year_match:
                copyright_year = copyright_year_match.group(1)
        elif release_date_match:
            tags["date"] = [release_date_match.group(1)]
        elif ": " in line:
            for tag_name, names in youtube_credits.parse_credit_line(line).items():
                utils.add_values(tags_to_update=tags, tag_name=tag_name, new_values=names)

    if "date" not in tags and copyright_year is not None:
        tags["date"] = [copyright_year]
    return tags
